import json

sources = {
    1: "The Falcon plan costs twenty dollars per month and includes ten projects.",
}

def build_json_output_prompt(sources, query):
    # specifying the exact schema
    context_block = "\n".join(f"[{k}] {v}" for k, v in sources.items())
    schema_example = json.dumps(
        {"answer": "string", "confidence": "high, medium, or low", "sources": [1]},
        indent=2,
    )
    return (
        f"Context:\n{context_block}\n\n"
        f"Question: {query}\n"
        f"Return only valid JSON matching this exact shape, nothing else:\n{schema_example}"
    )

query = "What does the Falcon plan cost?"
prompt = build_json_output_prompt(sources, query)
print("JSON output prompt:\n")
print(prompt)

def parse_json_response(response_text, retry_count=0):
    # validating the parsed result
    try:
        return json.loads(response_text)
    except json.JSONDecodeError:
        if retry_count == 0:
            print("Parse failed, would retry the request here.")
        return None

simulated_response = json.dumps(
    {"answer": "The Falcon plan costs twenty dollars per month.", "confidence": "high", "sources": [1]}
)
parsed = parse_json_response(simulated_response)
print("\nParsed JSON:")
print(parsed)
